//go:build amd64

package per

import (
	"github.com/thebagchi/asn1c-go/lib/cpu"
)

// How much input the assembly kernel handles per iteration: bytes in when
// encoding, characters in when decoding.
const (
	BIN_ENCODE_BLOCK = 8
	BIN_DECODE_BLOCK = 64
)

// The kernels are generated by avo from gen/bin.go into bin_amd64.s, with what
// every family shares in gen/main.go. The declarations at the end of this file
// are what Go sees of them, and go vet's asmdecl check holds them and the
// assembly's frames in step. Regenerate with "make generate".
//
//go:generate go run ./gen/main.go ./gen/numeric.go ./gen/hex.go ./gen/bin.go -only bin -out bin_amd64.s -pkg per

// BIN_AVX2 is the one assembly kernel this family has.
var (
	BIN_AVX2 = &_Kernel{
		name:        NAME_AVX2,
		have:        cpu.HAS_AVX2,
		encodeBlock: BIN_ENCODE_BLOCK,
		decodeBlock: BIN_DECODE_BLOCK,
		encode:      _BinaryEncodeAVX2,
		decode:      _BinaryDecodeAVX2,
	}
)

// _BinKernels lists every kernel amd64 has, narrowest first.
//
// Revisions:
//   - 2026-09-24 01:40: initial creation
func _BinKernels() []*_Kernel {
	return []*_Kernel{BIN_GO, BIN_AVX2}
}

// _EncodeBinary renders whole blocks of src with the kernel init selected and
// returns how many bytes it took; the caller finishes with the Go kernel, and
// kernel.go says why. The kernel is called by name for the reason
// bitbuffer._RunShift gives.
//
// Revisions:
//   - 2026-09-23 08:40: initial creation
//   - 2026-09-24 01:40: finishes with the Go kernel, and dispatches on the
//     kernel init selected
//   - 2026-09-24 02:00: the assembly kernel only, again; the Go kernel moved
//     to the caller
func _EncodeBinary(dst, src []byte) int {
	if BIN_KERNEL == BIN_AVX2 {
		return _BinaryEncodeAVX2(dst, src)
	}

	return 0
}

// _DecodeBinary parses whole blocks of src with the kernel init selected,
// stopping at the first block holding a character that is neither '0' nor
// '1', and returns how many characters it took; the caller finishes with the
// Go kernel.
//
// Revisions:
//   - 2026-09-23 08:40: initial creation
//   - 2026-09-24 01:40: finishes with the Go kernel, and dispatches on the
//     kernel init selected
//   - 2026-09-24 02:00: the assembly kernel only, again; the Go kernel moved
//     to the caller
func _DecodeBinary(dst, src []byte) int {
	if BIN_KERNEL == BIN_AVX2 {
		return _BinaryDecodeAVX2(dst, src)
	}

	return 0
}

// _BinaryEncodeAVX2 renders src as '0' and '1' characters into dst, leading bit
// first, eight bytes per iteration, and returns how many bytes it consumed: a
// multiple of eight. len(dst) must be at least 8*len(src). Declared noescape
// so a caller's stack buffer stays where it is; the same holds below.
//
// Revisions:
//   - 2026-09-23 09:10: initial creation, in place of the generated stub
//
//go:noescape
func _BinaryEncodeAVX2(dst, src []byte) int

// _BinaryDecodeAVX2 parses '0' and '1' characters from src into bytes in dst,
// leading character first, sixty-four characters per iteration, and returns
// how many characters it consumed: a multiple of sixty-four, short of len(src)
// when a block holds a character that is neither. len(dst) must be at least
// len(src)/8.
//
// Revisions:
//   - 2026-09-23 09:10: initial creation, in place of the generated stub
//
//go:noescape
func _BinaryDecodeAVX2(dst, src []byte) int
